def priority(item: float, bins: np.ndarray) -> np.ndarray:
    leftover = bins - item
    valid = leftover >= 0
    priority_scores = np.full_like(bins, -np.inf)

    if np.any(valid):
        valid_leftover = leftover[valid]
        exact_fit = valid_leftover == 0
        if np.any(exact_fit):
            priority_scores[valid] = np.where(exact_fit, 2, -np.inf)
        else:
            priority_scores[valid] = 1 / (valid_leftover + 1)
    return priority_scores
